			/* <flatten type="Javascript"> */
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'ma_dvcs');
	changeLookupReadonly(f, 'tk');
	changeLookupReadonly(f, 'ma_kh');
	changeLookupReadonly(f, 'ma_hd');
	&ReportSign.Filter.Active;
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, x = f.getItemValue('mau_bc');
			var dFrom = f.getItem('tu_ngay').value, dTo = f.getItem('den_ngay').value;
			g._alterTitle = [null, [['%d1', dFrom, true], ['%d2', dTo, true]]];
			g._hiddenFields = [
				{Fields: 'ps_no_nt, ps_co_nt, no_ck_nt, co_ck_nt, ma_nt, ty_gia', Value: (x == '10')},
			];
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

